// Regrouper le scénario d'ajout au panier depuis une fiche produit.
describe('Swag Labs product catalogue', () => {
  // Se connecter avant le scénario avec la commande partagée.
  beforeEach(() => {
    // Ouvrir une session utilisateur standard.
    cy.login();
  });

  // Fermer la session après le scénario avec la commande partagée.
  afterEach(() => {
    // Déconnecter l'utilisateur après la vérification.
    cy.logout();
  });

  // Définir le scénario d'ajout du Sauce Labs Backpack depuis sa fiche.
  it('ajoute le Sauce Labs Backpack au panier depuis sa fiche produit', () => {
    // Ouvrir la fiche du Sauce Labs Backpack depuis le catalogue.
    cy.get('[data-test="item-4-title-link"]').click();
    // Vérifier que la bonne fiche produit est affichée.
    cy.get('[data-test="inventory-item-name"]').should('be.visible').and('have.text', 'Sauce Labs Backpack');

    // Ajouter le produit au panier depuis sa fiche.
    cy.get('[data-test="add-to-cart"]').click();

    // Vérifier que le bouton indique que le produit peut être retiré du panier.
    cy.get('[data-test="remove"]').should('be.visible').and('have.text', 'Remove');
    // Vérifier que le badge du panier indique un produit.
    cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '1');
  });
});
